// generar_301_visitas_en_novedades_y_dashboard.js
// CHIQUI Entre Señales — Visitas veterinarias en Novedades y Próximos (Etapa 2 y 3)
//
// Completa la función de visitas veterinarias integrándola con el
// dashboard. Ahora, además de la sección en Salud (script 300):
//
//   1. NOVEDADES: si hay una visita agendada dentro de los próximos 7
//      días, aparece una tarjeta de aviso en el dashboard ("La visita
//      al veterinario de [mascota] es en 3 días (motivo) en [clínica]"),
//      con Chiqui veterinario y acción para ir a verla.
//
//   2. PRÓXIMOS: la visita más cercana aparece también en la grilla
//      "Próximos" del dashboard, junto a vacunas, antiparasitarios, etc.,
//      mostrando los días que faltan.
//
// Los datos salen de la tabla visitas_veterinarias (creada en el script
// 300 con su SQL). El dashboard las carga y las reparte a Novedades y a
// la grilla de Próximos.
//
// ⚠️ Requiere que ya hayas corrido el script 300 y su SQL. No hay SQL
//    nuevo en este script.
//
// Uso:
//   node generar_301_visitas_en_novedades_y_dashboard.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "components/Novedades.tsx",
    base64: ""
  },
  {
    ruta: "components/DashboardContenido.tsx",
    base64: ""
  },
  {
    ruta: "app/dashboard/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 3 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
